                c += 1
            end = c - 1
            if end - start < 1:
                continue
            values = tuple(grid[r][start:end + 1])
            rr = r + 1
            while rr < h and tuple(grid[rr][start:end + 1]) == values:
                rr += 1
            if rr - r >= 2:
                size = (rr - r) * (end - start + 1)
                if strip is None or size > strip[0]:
                    strip = (size, r, rr - 1, start, end, list(values))

    if strip is None:
        return [row[:] for row in grid]

    _, sr0, sr1, sc0, sc1, sequence = strip
    excluded = {(r, c) for r in range(sr0, sr1 + 1)
                for c in range(sc0, sc1 + 1)}

