                continue
            stack = [(r, c)]
            seen.add((r, c))
            cells = []
            while stack:
                y, x = stack.pop()
                cells.append((y, x))
                for dy in (-1, 0, 1):
                    for dx in (-1, 0, 1):
                        if dy == 0 and dx == 0:
                            continue
                        ny, nx = y + dy, x + dx
                        if (0 <= ny < h and 0 <= nx < w and
                                (ny, nx) not in excluded and
                                grid[ny][nx] == color and
                                (ny, nx) not in seen):
                            seen.add((ny, nx))
                            stack.append((ny, nx))
            components.append((color, cells))

    color, cells = max(components, key=lambda item: len(item[1]))
    top = min(r for r, _ in cells)
    left = min(c for _, c in cells)
    height = max(r for r, _ in cells) - top + 1
    mask = [(r - top, c - left) for r, c in cells]

    if color not in sequence:
        return [row[:] for row in grid]
    anchor = sequence.index(color)

    out = [[0] * w for _ in range(h)]
    for i, new_color in enumerate(sequence):
